(function(){'use strict';window.showToast=window.LSM.showToast;window.escapeHtml=window.LSM.escapeHtml;window.escapeJs=window.LSM.escapeJs;window.ensureCsrfToken=window.LSM.ensureCsrfToken;window.formatDate=window.LSM.formatDate;window.isAdmin=window.LSM.isAdmin;window.doLogout=async function(){var csrfToken='';try{csrfToken=await window.LSM.ensureCsrfToken();}catch(e){csrfToken=window.__csrf_token||'';}
try{await fetch('/api/auth/logout',{method:'POST',headers:{'X-CSRF-Token':csrfToken},credentials:'same-origin'});}catch(e){}
window.location.href='/login';};document.addEventListener('DOMContentLoaded',function(){if(localStorage.getItem('encrypt_key_dismissed'))return;fetch('/api/auth/encrypt-key-status',{credentials:'same-origin'}).then(function(r){return r.json();}).then(function(data){if(!data.has_custom_key){showEncryptKeyBanner();}}).catch(function(){});});function showEncryptKeyBanner(){var content=document.querySelector('.content-body');if(!content)return;var banner=document.createElement('div');banner.id='encrypt-key-banner';banner.className='encrypt-banner';banner.innerHTML='<div class="encrypt-banner-text">'+'<span class="encrypt-banner-icon" aria-hidden="true">'+LSM.icon('lock')+'</span>'+'<span>系统使用<strong>自动生成的加密密钥</strong>，建议设置自定义环境变量 '+'<code>CONFIG_ENCRYPT_KEY</code> 以增强安全性。'+'<a href="/config">前往配置页</a></span>'+'</div>'+'<button type="button" class="encrypt-banner-close" aria-label="不再提示" title="我知道了，不再提示">✕</button>';banner.querySelector('.encrypt-banner-close').addEventListener('click',dismissEncryptKeyBanner);content.insertBefore(banner,content.firstChild);}
function dismissEncryptKeyBanner(){localStorage.setItem('encrypt_key_dismissed','1');var banner=document.getElementById('encrypt-key-banner');if(banner)banner.remove();}
document.addEventListener('DOMContentLoaded',function(){window.LSM.ensureCsrfToken();});})();